add_action( 'woocommerce_product_query', 'perfectpixel_hide_shop_page_products' );
add_action( 'woocommerce_no_products_found', 'perfectpixel_hide_shop_page_no_products_notice', 1 );

function perfectpixel_hide_shop_page_products( $q ) {
	if ( is_shop() && ! is_search() ) {
		$q->set( 'post__in', array( 0 ) );
	}
}

// Also drop the "No products were found" notice on the shop page.
function perfectpixel_hide_shop_page_no_products_notice() {
	if ( is_shop() && ! is_search() ) {
		remove_action( 'woocommerce_no_products_found', 'wc_no_products_found', 10 );
	}
}
